//! `vis optimize` — the native port of the report `src/commands/optimize/handler.ts` prints when no terminal
//! is attached: the `module-replacements` and `@socketregistry` entries that match the dependencies of the
//! workspace, as pail text or (`--format json`) as JSON.
//!
//! The replacement data is `optimize-tables.json`, generated by `src/commands/optimize/native-tables.ts` from the
//! functions the Node handler runs and guarded by `__tests__/native/optimize-tables.test.ts`, so a dependency
//! bump cannot change one side only. The binary answers only the context it can prove, like `clean` and
//! `sort-package-json`: CI, no terminal, no `vis.config.*`, a pnpm workspace whose root is the working
//! directory, and pail output it can reproduce. It hands everything else to Node before printing anything:
//!
//! - every shape that is interactive or applies anything (a terminal, which is the TUI), and every flag outside
//!   `--dry-run`/`-d`, `--format table|json`, `--no-install`, `--pin` and `--prod`;
//! - a package manager other than pnpm, a workspace pattern or `.gitignore` line outside the subsets of
//!   [`crate::workspace`], and a `package.json` that is not strict JSON (Node may read it differently);
//! - a character other than printable ASCII and the two symbols the report prints (`→`, `⚙`), which pail would
//!   measure in a way this crate does not reproduce (lines that need wrapping are wrapped like pail does it).
//!
//! Nothing is written, so a delegation never follows a change to a file.

use std::collections::BTreeSet;
use std::env;
use std::ffi::OsString;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::exit;

use serde::Deserialize;
use serde_json::Value;
use vis_core::detect::detect_package_manager;

use crate::js::is_js_whitespace;
use crate::json::Json;
use crate::node_context::{ci_root_context, quiet_context};
use crate::output::write_stdout;
use crate::pail::{Layout, Level};
use crate::vis_config::{self, ConfigState};
use crate::workspace::directories_with_package_json;

const TABLES_JSON: &str = include_str!("../optimize-tables.json");

/// `[category, package, replacement, hasCodemod]` and `[package, replacement, spec, pinnedSpec]` rows.
#[derive(Deserialize)]
struct Tables {
    e18e: Vec<(String, String, String, bool)>,
    socket: Vec<(String, String, String, String)>,
}

#[derive(Default)]
struct Options {
    dry_run: bool,
    json: bool,
    pin: bool,
    prod: bool,
}

/// One entry of the e18e part of the report.
struct E18e<'a> {
    category: &'a str,
    package: &'a str,
    replacement: &'a str,
    codemod: bool,
}

/// One entry of the Socket.dev part of the report.
struct Socket<'a> {
    package: &'a str,
    replacement: &'a str,
    spec: &'a str,
}

/// Answer `vis optimize` natively, or delegate to Node. `args` is the lossy view used for matching,
/// `raw_args` the untouched argv handed to Node. Never returns.
pub fn run(args: &[String], raw_args: &[OsString]) -> ! {
    let Some(options) = parse(args) else {
        crate::process::delegate(raw_args);
    };
    let Some((layout, cwd)) = context(args) else {
        crate::process::delegate(raw_args);
    };
    let Some(tables) = serde_json::from_str::<Tables>(TABLES_JSON).ok() else {
        crate::process::delegate(raw_args);
    };
    let Some(output) = report(&options, layout, &cwd, &tables) else {
        crate::process::delegate(raw_args);
    };

    write_stdout("optimize", "the output", &output);

    exit(0)
}

/// The flags this path understands, or `None` when the invocation needs Node. `args` is the full argv, so the
/// first word is `optimize`. Each flag may appear once; `--format` takes `table` or `json`, as `--format value`
/// or `--format=value`.
fn parse(args: &[String]) -> Option<Options> {
    let mut options = Options::default();
    let mut seen: Vec<&str> = Vec::new();
    let mut index = 1;

    // A lossy argv conversion turns invalid UTF-8 into U+FFFD. Node would see the raw bytes.
    if args.iter().any(|argument| argument.contains('\u{FFFD}')) {
        return None;
    }

    while index < args.len() {
        let token = args[index].as_str();
        let (name, inline) = match token.split_once('=') {
            Some((name, value)) if name == "--format" => (name, Some(value)),
            _ => (token, None),
        };

        let flag = match (name, inline) {
            ("--dry-run" | "-d", None) => {
                options.dry_run = true;
                "--dry-run"
            }
            ("--pin", None) => {
                options.pin = true;
                name
            }
            ("--prod", None) => {
                options.prod = true;
                name
            }
            ("--no-install", None) => name,
            ("--format", _) => {
                let value = match inline {
                    Some(value) => value,
                    None => {
                        index += 1;

                        args.get(index)?.as_str()
                    }
                };

                options.json = match value {
                    "json" => true,
                    "table" => false,
                    _ => return None,
                };
                name
            }
            _ => return None,
        };

        if seen.contains(&flag) {
            return None;
        }

        seen.push(flag);
        index += 1;
    }

    Some(options)
}

/// Whether Node would reach the same answer, and the layout pail prints in. `None` is a delegation.
fn context(args: &[String]) -> Option<(Layout, PathBuf)> {
    let layout = Layout::detect(args)?;
    let cwd = env::current_dir().ok()?;

    // Node works from the workspace root, which this crate finds for a pnpm workspace; the report is the
    // same only when that root is the working directory.
    if !ci_root_context(&cwd) || !quiet_context(&cwd, &cwd) || vis_config::read(&cwd) != ConfigState::Absent {
        return None;
    }

    Some((layout, cwd))
}

/// The text of the whole run, or `None` when something on the way is outside what this module reproduces.
fn report(options: &Options, layout: Layout, cwd: &Path, tables: &Tables) -> Option<String> {
    let detected = detect_package_manager(cwd.to_str()?, None);

    if detected.name != "pnpm" {
        return None;
    }

    // `detected.version || "latest"`.
    let version = detected.version.filter(|version| !version.is_empty()).unwrap_or_else(|| "latest".to_owned());
    let directories = directories_with_package_json(cwd)?;

    let mut dependencies = read_dependencies(&cwd.join("package.json"), options.prod)?;

    for directory in &directories {
        dependencies.extend(read_dependencies(&cwd.join(directory).join("package.json"), options.prod)?);
    }

    let mut out = String::new();
    let mut say = |level: Level, message: &str| -> Option<()> {
        out.push_str(&layout.block_fitting(level, message)?);

        Some(())
    };

    say(Level::Info, &format!("Detected pnpm v{version}."))?;

    if !directories.is_empty() {
        let count = directories.len();

        say(Level::Info, &format!("Scanned {count} workspace package{}.", if count == 1 { "" } else { "s" }))?;
    }

    say(Level::Info, "Scanning dependencies...\n")?;

    let lockfile = String::from_utf8_lossy(&fs::read(cwd.join("pnpm-lock.yaml")).unwrap_or_default()).into_owned();
    let e18e: Vec<E18e> = tables
        .e18e
        .iter()
        .filter(|(_, package, ..)| dependencies.contains(package))
        .map(|(category, package, replacement, codemod)| E18e { category, package, replacement, codemod: *codemod })
        .collect();
    // An e18e entry wins over an override of the same package.
    let socket: Vec<Socket> = tables
        .socket
        .iter()
        .filter(|(package, ..)| dependencies.contains(package) || lockfile_contains(&lockfile, package))
        .filter(|(package, ..)| !e18e.iter().any(|entry| entry.package == package))
        .map(|(package, replacement, spec, pinned)| Socket {
            package,
            replacement,
            spec: if options.pin { pinned } else { spec },
        })
        .collect();
    let total = e18e.len() + socket.len();

    if total == 0 {
        say(Level::Info, "No optimizations found for your dependencies.")?;

        return Some(out);
    }

    if options.json {
        out.push_str(&json_report(&e18e, &socket, total, directories.len()));

        return Some(out);
    }

    for (category, title, lead) in [
        ("native", "Native replacements", ""),
        ("preferred", "Preferred alternatives", "\n"),
        ("micro-utility", "Micro-utilities", "\n"),
    ] {
        let entries: Vec<&E18e> = e18e.iter().filter(|entry| entry.category == category).collect();

        if entries.is_empty() {
            continue;
        }

        say(Level::Info, &format!("{lead}{title} ({}):", entries.len()))?;

        for entry in entries {
            say(
                Level::Info,
                &format!(
                    "  {} {} \u{2192} {}",
                    if entry.codemod { "\u{2699}" } else { " " },
                    entry.package,
                    entry.replacement
                ),
            )?;
        }
    }

    if !socket.is_empty() {
        say(Level::Info, &format!("\nSocket.dev overrides ({}):", socket.len()))?;

        for entry in &socket {
            say(Level::Info, &format!("  {} \u{2192} {}", entry.package, entry.spec))?;
        }
    }

    say(Level::Info, &format!("\nTotal: {total} optimizations available (\u{2699} = codemod available)."))?;

    if options.dry_run {
        say(Level::Notice, "Run without --dry-run for interactive selection.")?;
    }

    Some(out)
}

/// `JSON.stringify(report, undefined, 2)` and a newline. The keys are in the order the handler builds them.
fn json_report(e18e: &[E18e], socket: &[Socket], total: usize, workspaces: usize) -> String {
    let text = |value: &str| Json::Str(value.to_owned());
    let number = |value: usize| Json::Int(i64::try_from(value).unwrap_or(i64::MAX));
    let report = Json::Object(vec![
        (
            "e18e".to_owned(),
            Json::Array(
                e18e.iter()
                    .map(|entry| {
                        Json::Object(vec![
                            ("category".to_owned(), text(entry.category)),
                            ("hasCodemod".to_owned(), Json::Bool(entry.codemod)),
                            ("packageName".to_owned(), text(entry.package)),
                            ("replacement".to_owned(), text(entry.replacement)),
                        ])
                    })
                    .collect(),
            ),
        ),
        ("packageManager".to_owned(), text("pnpm")),
        (
            "socket".to_owned(),
            Json::Array(
                socket
                    .iter()
                    .map(|entry| {
                        Json::Object(vec![
                            ("overrideSpec".to_owned(), text(entry.spec)),
                            ("packageName".to_owned(), text(entry.package)),
                            ("replacement".to_owned(), text(entry.replacement)),
                        ])
                    })
                    .collect(),
            ),
        ),
        ("total".to_owned(), number(total)),
        ("workspaces".to_owned(), number(workspaces)),
    ]);

    format!("{}\n", crate::json::stringify(&report, "  "))
}

/// `collectDepsFromPkgJson`: the dependency names of one manifest. A file that cannot be read gives none, as the
/// handler's `catch` does; a file that is not strict JSON, or a dependency map JavaScript would read in a way
/// this crate does not reproduce, is `None`.
fn read_dependencies(manifest: &Path, production_only: bool) -> Option<BTreeSet<String>> {
    let mut names = BTreeSet::new();

    let Ok(bytes) = fs::read(manifest) else {
        return Some(names);
    };

    let manifest: Value = serde_json::from_str(std::str::from_utf8(&bytes).ok()?).ok()?;
    let keys: &[&str] = if production_only {
        &["dependencies", "optionalDependencies"]
    } else {
        &["dependencies", "devDependencies", "peerDependencies", "optionalDependencies"]
    };

    for key in keys {
        match manifest.get(*key) {
            None | Some(Value::Null | Value::Bool(false)) => {}
            Some(Value::Object(map)) => {
                names.extend(map.keys().cloned());
            }
            // A string, a number or an array: `Object.keys` lists indices or characters.
            Some(value) if is_falsy(value) => {}
            Some(_) => return None,
        }
    }

    Some(names)
}

/// JavaScript falsiness of a JSON value other than `null` and `false`: `0` and the empty string.
fn is_falsy(value: &Value) -> bool {
    match value {
        Value::Number(number) => number.as_f64().is_some_and(|number| number == 0.0),
        Value::String(text) => text.is_empty(),
        _ => false,
    }
}

/// `lockfileContainsPackage` for pnpm: `/(^|\s|['"/])<name>(@|['"]?:)/m` over the lockfile text.
fn lockfile_contains(text: &str, package: &str) -> bool {
    if text.is_empty() {
        return false;
    }

    text.match_indices(package).any(|(start, _)| {
        let before = text[..start].chars().next_back();
        let boundary =
            before.is_none_or(|character| is_js_whitespace(character) || matches!(character, '\'' | '"' | '/'));
        let rest = &text[start + package.len()..];
        let after = rest.starts_with('@') || rest.strip_prefix(['\'', '"']).unwrap_or(rest).starts_with(':');

        boundary && after
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn args(words: &[&str]) -> Vec<String> {
        std::iter::once("optimize").chain(words.iter().copied()).map(str::to_owned).collect()
    }

    #[test]
    fn the_shipped_tables_parse() {
        let tables: Tables = serde_json::from_str(TABLES_JSON).unwrap();

        assert!(!tables.socket.is_empty());
    }

    #[test]
    fn flags_are_taken_once_and_only_known_ones() {
        assert!(parse(&args(&[])).is_some());
        assert!(parse(&args(&["--dry-run", "--pin", "--prod", "--no-install", "--format", "json"])).is_some());
        assert!(parse(&args(&["-d", "--format=table"])).is_some());
        assert!(parse(&args(&["--dry-run", "-d"])).is_none());
        assert!(parse(&args(&["--format", "xml"])).is_none());
        assert!(parse(&args(&["--format"])).is_none());
        assert!(parse(&args(&["--json"])).is_none());
        assert!(parse(&args(&["pkg"])).is_none());
    }

    #[test]
    fn the_lockfile_match_follows_the_pnpm_pattern() {
        let text = "packages:\n  /abab@1.0.0:\n    resolution: x\n  'left-pad':\n  other: left-pad@1\nx.abab:\n";

        assert!(lockfile_contains(text, "abab"));
        assert!(lockfile_contains(text, "left-pad"));
        assert!(!lockfile_contains(text, "ab"));
        assert!(!lockfile_contains(text, "pad"));
        assert!(!lockfile_contains("", "abab"));
        assert!(lockfile_contains("abab: 1", "abab"));
        assert!(lockfile_contains("\u{a0}abab@1", "abab"));
        assert!(!lockfile_contains("xabab@1", "abab"));
    }

    #[test]
    fn dependency_maps_follow_object_keys() {
        let dir = std::env::temp_dir().join(format!("vis-optimize-{}", std::process::id()));

        fs::create_dir_all(&dir).unwrap();

        let path = dir.join("package.json");

        fs::write(&path, r#"{"dependencies":{"a":"1"},"devDependencies":{"b":"1"},"peerDependencies":null,"optionalDependencies":{}}"#).unwrap();

        assert_eq!(read_dependencies(&path, false).unwrap().into_iter().collect::<Vec<_>>(), ["a", "b"]);
        assert_eq!(read_dependencies(&path, true).unwrap().into_iter().collect::<Vec<_>>(), ["a"]);

        fs::write(&path, r#"{"dependencies":"abc"}"#).unwrap();

        assert!(read_dependencies(&path, false).is_none());

        fs::write(&path, r#"{"dependencies":0, "devDependencies": []}"#).unwrap();

        assert!(read_dependencies(&path, false).is_none());

        fs::write(&path, "{ not json").unwrap();

        assert!(read_dependencies(&path, false).is_none());
        assert!(read_dependencies(&dir.join("missing.json"), false).unwrap().is_empty());

        let _ = fs::remove_dir_all(&dir);
    }

    /// A pnpm workspace in a scratch directory with `dependencies` in its root manifest.
    fn workspace(name: &str, dependencies: &[&str]) -> PathBuf {
        let dir = std::env::temp_dir().join(format!("vis-optimize-report-{}-{name}", std::process::id()));
        let manifest = serde_json::json!({ "name": "root", "dependencies": dependencies.iter().map(|name| ((*name).to_owned(), Value::from("1"))).collect::<serde_json::Map<String, Value>>() });

        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        fs::write(dir.join("package.json"), manifest.to_string()).unwrap();
        fs::write(dir.join("pnpm-lock.yaml"), "lockfileVersion: 9\n").unwrap();
        fs::write(dir.join("pnpm-workspace.yaml"), "packages:\n  - \"packages/*\"\n").unwrap();

        dir
    }

    /// The e18e lists are empty with the shipped manifests, so the branches that print them run on a synthetic table.
    fn synthetic() -> Tables {
        let row = |category: &str, package: &str, replacement: &str, codemod: bool| {
            (category.to_owned(), package.to_owned(), replacement.to_owned(), codemod)
        };

        Tables {
            e18e: vec![
                row("native", "left-pad", "String.prototype.padStart (Node 8+)", true),
                row("preferred", "chalk", "see migration guide", false),
                row("micro-utility", "is-number", "", false),
                row("native", "not-used", "x", false),
            ],
            socket: vec![
                (
                    "chalk".to_owned(),
                    "@socketregistry/chalk".to_owned(),
                    "npm:@socketregistry/chalk@^1".to_owned(),
                    "npm:@socketregistry/chalk@1.0.0".to_owned(),
                ),
                (
                    "abab".to_owned(),
                    "@socketregistry/abab".to_owned(),
                    "npm:@socketregistry/abab@^1".to_owned(),
                    "npm:@socketregistry/abab@1.0.9".to_owned(),
                ),
            ],
        }
    }

    #[test]
    fn e18e_entries_print_by_category_and_win_over_an_override() {
        let dir = workspace("text", &["left-pad", "chalk", "is-number", "abab"]);
        let layout = Layout { width: 100, colour: false };
        let text = report(&Options::default(), layout, &dir, &synthetic()).unwrap();
        let _ = fs::remove_dir_all(&dir);
        let body: Vec<&str> = text.lines().filter(|line| !line.is_empty() && !line.contains(" INFO ...")).collect();

        assert_eq!(
            body,
            [
                "Detected pnpm vlatest.",
                "Scanning dependencies...",
                "Native replacements (1):",
                "  \u{2699} left-pad \u{2192} String.prototype.padStart (Node 8+)",
                "Preferred alternatives (1):",
                "    chalk \u{2192} see migration guide",
                "Micro-utilities (1):",
                "    is-number \u{2192} ",
                "Socket.dev overrides (1):",
                "  abab \u{2192} npm:@socketregistry/abab@^1",
                "Total: 4 optimizations available (\u{2699} = codemod available).",
            ]
        );
    }

    #[test]
    fn e18e_entries_are_in_the_json_with_their_codemod_flag() {
        let dir = workspace("json", &["left-pad", "chalk"]);
        let layout = Layout { width: 100, colour: false };
        let options = Options { json: true, ..Options::default() };
        let text = report(&options, layout, &dir, &synthetic()).unwrap();
        let _ = fs::remove_dir_all(&dir);
        let report: Value = serde_json::from_str(&text[text.find('{').unwrap()..]).unwrap();

        assert_eq!(
            report,
            serde_json::json!({
                "e18e": [
                    { "category": "native", "hasCodemod": true, "packageName": "left-pad", "replacement": "String.prototype.padStart (Node 8+)" },
                    { "category": "preferred", "hasCodemod": false, "packageName": "chalk", "replacement": "see migration guide" },
                ],
                "packageManager": "pnpm",
                "socket": [],
                "total": 2,
                "workspaces": 0,
            })
        );
    }
}
